Here's a complete C++ Qt5 application that creates a GUI for converting Excel files to CSV:

## main.cpp
```cpp
#include <QApplication>
#include "ExcelToCsvConverter.h"

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);

    ExcelToCsvConverter converter;
    converter.show();

    return app.exec();
}
```

## ExcelToCsvConverter.h
```cpp
#ifndef EXCELTOCSVCONVERTER_H
#define EXCELTOCSVCONVERTER_H

#include <QWidget>
#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QPushButton>
#include <QLabel>
#include <QLineEdit>
#include <QProgressBar>
#include <QTextEdit>
#include <QFileDialog>
#include <QMessageBox>
#include <QDir>
#include <QFileInfo>
#include <QStringList>
#include <QAxObject>
#include <QApplication>
#include <QThread>
#include <QMutex>

class ExcelToCsvConverter : public QWidget
{
    Q_OBJECT

public:
    explicit ExcelToCsvConverter(QWidget *parent = nullptr);
    ~ExcelToCsvConverter();

private slots:
    void selectDirectory();
    void convertFiles();
    void onConversionFinished(int convertedCount, int totalCount);
    void onConversionError(const QString &error);
    void onProgressUpdate(int current, int total);

private:
    void setupUI();
    void enableControls(bool enabled);

    // UI Components
    QVBoxLayout *m_mainLayout;
    QHBoxLayout *m_directoryLayout;
    QLineEdit *m_directoryEdit;
    QPushButton *m_browseButton;
    QPushButton *m_convertButton;
    QProgressBar *m_progressBar;
    QTextEdit *m_logTextEdit;
    QLabel *m_statusLabel;

    QString m_selectedDirectory;
};

// Worker class for handling Excel conversion in separate thread
class ExcelConverterWorker : public QObject
{
    Q_OBJECT

public:
    explicit ExcelConverterWorker(const QString &directory, QObject *parent = nullptr);

public slots:
    void process();

signals:
    void progressUpdated(int current, int total);
    void finished(int convertedCount, int totalCount);
    void error(const QString &errorMessage);

private:
    bool convertExcelToCsv(const QString &excelPath, const QString &csvPath);
    QString m_directory;
};

#endif // EXCELTOCSVCONVERTER_H
```

## ExcelToCsvConverter.cpp
```cpp
#include "ExcelToCsvConverter.h"
#include <QDebug>
#include <QDateTime>

ExcelToCsvConverter::ExcelToCsvConverter(QWidget *parent)
    : QWidget(parent)
    , m_mainLayout(nullptr)
    , m_directoryLayout(nullptr)
    , m_directoryEdit(nullptr)
    , m_browseButton(nullptr)
    , m_convertButton(nullptr)
    , m_progressBar(nullptr)
    , m_logTextEdit(nullptr)
    , m_statusLabel(nullptr)
{
    setupUI();
    setWindowTitle("Excel to CSV Converter");
    setMinimumSize(600, 400);
}

ExcelToCsvConverter::~ExcelToCsvConverter()
{
}

void ExcelToCsvConverter::setupUI()
{
    m_mainLayout = new QVBoxLayout(this);

    // Directory selection section
    m_directoryLayout = new QHBoxLayout();
    m_directoryEdit = new QLineEdit();
    m_directoryEdit->setPlaceholderText("Select a directory containing Excel files...");
    m_directoryEdit->setReadOnly(true);

    m_browseButton = new QPushButton("Browse");
    connect(m_browseButton, &QPushButton::clicked, this, &ExcelToCsvConverter::selectDirectory);

    m_directoryLayout->addWidget(new QLabel("Directory:"));
    m_directoryLayout->addWidget(m_directoryEdit);
    m_directoryLayout->addWidget(m_browseButton);

    // Convert button
    m_convertButton = new QPushButton("Convert Excel Files to CSV");
    m_convertButton->setEnabled(false);
    connect(m_convertButton, &QPushButton::clicked, this, &ExcelToCsvConverter::convertFiles);

    // Progress bar
    m_progressBar = new QProgressBar();
    m_progressBar->setVisible(false);

    // Status label
    m_statusLabel = new QLabel("Please select a directory to begin.");

    // Log text area
    m_logTextEdit = new QTextEdit();
    m_logTextEdit->setMaximumHeight(150);
    m_logTextEdit->setPlaceholderText("Conversion log will appear here...");

    // Add widgets to main layout
    m_mainLayout->addLayout(m_directoryLayout);
    m_mainLayout->addWidget(m_convertButton);
    m_mainLayout->addWidget(m_progressBar);
    m_mainLayout->addWidget(m_statusLabel);
    m_mainLayout->addWidget(new QLabel("Log:"));
    m_mainLayout->addWidget(m_logTextEdit);
}

void ExcelToCsvConverter::selectDirectory()
{
    QString directory = QFileDialog::getExistingDirectory(
        this,
        "Select Directory with Excel Files",
        QString(),
        QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks
    );

    if (!directory.isEmpty()) {
        m_selectedDirectory = directory;
        m_directoryEdit->setText(directory);
        m_convertButton->setEnabled(true);
        m_statusLabel->setText("Directory selected. Ready to convert.");

        // Count Excel files in directory
        QDir dir(directory);
        QStringList filters;
        filters << "*.xlsx" << "*.xls" << "*.xlsm";
        QFileInfoList excelFiles = dir.entryInfoList(filters, QDir::Files);

        m_logTextEdit->append(QString("Found %1 Excel file(s) in selected directory.").arg(excelFiles.count()));
    }
}

void ExcelToCsvConverter::convertFiles()
{
    if (m_selectedDirectory.isEmpty()) {
        QMessageBox::warning(this, "Warning", "Please select a directory first.");
        return;
    }

    enableControls(false);
    m_progressBar->setVisible(true);
    m_progressBar->setValue(0);
    m_statusLabel->setText("Converting files...");
    m_logTextEdit->append(QString("\n--- Conversion started at %1 ---").arg(QDateTime::currentDateTime().toString()));

    // Create worker and thread
    QThread *thread = new QThread;
    ExcelConverterWorker *worker = new ExcelConverterWorker(m_selectedDirectory);
    worker->moveToThread(thread);

    // Connect signals
    connect(thread, &QThread::started, worker, &ExcelConverterWorker::process);
    connect(worker, &ExcelConverterWorker::progressUpdated, this, &ExcelToCsvConverter::onProgressUpdate);
    connect(worker, &ExcelConverterWorker::finished, this, &ExcelToCsvConverter::onConversionFinished);
    connect(worker, &ExcelConverterWorker::error, this, &ExcelToCsvConverter::onConversionError);
    connect(worker, &ExcelConverterWorker::finished, thread, &QThread::quit);
    connect(thread, &QThread::finished, worker, &QObject::deleteLater);
    connect(thread, &QThread::finished, thread, &QObject::deleteLater);

    thread->start();
}

void ExcelToCsvConverter::onProgressUpdate(int current, int total)
{
    m_progressBar->setMaximum(total);
    m_progressBar->setValue(current);
    m_statusLabel->setText(QString("Converting file %1 of %2...").arg(current).arg(total));
}

void ExcelToCsvConverter::onConversionFinished(int convertedCount, int totalCount)
{
    enableControls(true);
    m_progressBar->setVisible(false);
    m_statusLabel->setText(QString("Conversion completed! %1 of %2 files converted successfully.")
                          .arg(convertedCount).arg(totalCount));

    m_logTextEdit->append(QString("--- Conversion completed at %1 ---").arg(QDateTime::currentDateTime().toString()));
    m_logTextEdit->append(QString("Successfully converted %1 out of %2 files.").arg(convertedCount).arg(totalCount));

    if (convertedCount > 0) {
        QMessageBox::information(this, "Success", 
            QString("Successfully converted %1 Excel file(s) to CSV.\nCSV files saved in 'csv_output' folder.")
            .arg(convertedCount));
    }
}

void ExcelToCsvConverter::onConversionError(const QString &error)
{
    enableControls(true);
    m_progressBar->setVisible(false);
    m_statusLabel->setText("Conversion failed with errors.");
    m_logTextEdit->append(QString("ERROR: %1").arg(error));
    QMessageBox::critical(this, "Error", error);
}

void ExcelToCsvConverter::enableControls(bool enabled)
{
    m_browseButton->setEnabled(enabled);
    m_convertButton->setEnabled(enabled);
}

// Worker class implementation
ExcelConverterWorker::ExcelConverterWorker(const QString &directory, QObject *parent)
    : QObject(parent), m_directory(directory)
{
}

void ExcelConverterWorker::process()
{
    QDir sourceDir(m_directory);

    // Create output directory
    QString outputDirPath = sourceDir.absoluteFilePath("csv_output");
    QDir outputDir;
    if (!outputDir.exists(outputDirPath)) {
        if (!outputDir.mkpath(outputDirPath)) {
            emit error("Failed to create output directory: " + outputDirPath);
            return;
        }
    }

    // Find all Excel files
    QStringList filters;
    filters << "*.xlsx" << "*.xls" << "*.xlsm";
    QFileInfoList excelFiles = sourceDir.entryInfoList(filters, QDir::Files);

    if (excelFiles.isEmpty()) {
        emit error("No Excel files found in the selected directory.");
        return;
    }

    int convertedCount = 0;
    int totalCount = excelFiles.count();

    for (int i = 0; i < excelFiles.count(); ++i) {
        emit progressUpdated(i + 1, totalCount);

        const QFileInfo &fileInfo = excelFiles.at(i);
        QString csvFileName = fileInfo.baseName() + ".csv";
        QString csvFilePath = outputDir.absoluteFilePath(outputDirPath + "/" + csvFileName);

        if (convertExcelToCsv(fileInfo.absoluteFilePath(), csvFilePath)) {
            convertedCount++;
        }
    }

    emit finished(convertedCount, totalCount);
}

bool ExcelConverterWorker::convertExcelToCsv(const QString &excelPath, const QString &csvPath)
{
    // Note: This requires Microsoft Office to be installed on Windows
    // For cross-platform solution, consider using libxls or similar library

    try {
        QAxObject *excel = new QAxObject("Excel.Application");
        excel->setProperty("Visible", false);
        excel->setProperty("DisplayAlerts", false);

        QAxObject *workbooks = excel->querySubObject("Workbooks");
        QAxObject *workbook = workbooks->querySubObject("Open(const QString&)", excelPath);

        if (workbook) {
            // Save as CSV (format 6 = CSV)
            workbook->dynamicCall("SaveAs(const QString&, int)", csvPath, 6);
            workbook->dynamicCall("Close()");
        }

        excel->dynamicCall("Quit()");
        delete excel;

        return QFile::exists(csvPath);
    }
    catch (...) {
        return false;
    }
}

#include "ExcelToCsvConverter.moc"
```

## CMakeLists.txt
```cmake
cmake_minimum_required(VERSION 3.16)
project(ExcelToCsvConverter)

set(CMAKE_CXX_STANDARD 17)
set(CMAKE_CXX_STANDARD_REQUIRED ON)

find_package(Qt5 REQUIRED COMPONENTS Core Widgets AxContainer)

set(CMAKE_AUTOMOC ON)

add_executable(ExcelToCsvConverter
    main.cpp
    ExcelToCsvConverter.cpp
    ExcelToCsvConverter.h
)

target_link_libraries(ExcelToCsvConverter
    Qt5::Core
    Qt5::Widgets
    Qt5::AxContainer
)
```

## Alternative .pro file (if using qmake)
```pro
QT += core widgets axcontainer
CONFIG += c++17

TARGET = ExcelToCsvConverter
TEMPLATE = app

SOURCES += \
    main.cpp \
    ExcelToCsvConverter.cpp

HEADERS += \
    ExcelToCsvConverter.h
```

## Key Features:

1. **Simple GUI** with directory selection and convert button
2. **Progress tracking** with progress bar and status updates
3. **Threaded conversion** to prevent UI freezing
4. **Error handling** and user feedback
5. **Automatic output folder** creation (`csv_output` directory)
6. **Log display** showing conversion progress and results

## Important Notes:

1. **Windows Only**: This code uses `QAxObject` which requires Microsoft Office to be installed on Windows. For cross-platform solutions, you'd need to use libraries like `libxlsxwriter` or `xlnt`.

2. **Dependencies**: Make sure to link against `Qt5::AxContainer` for COM automation.

3. **File Formats**: Supports `.xlsx`, `.xls`, and `.xlsm` files.

4. **Output**: Creates a `csv_output` folder in the selected directory containing all converted CSV files.

To compile and run:
1. Make sure Qt5 and Microsoft Office are installed
2. Use either CMake or qmake to build the project
3. Run the executable

The application provides a user-friendly interface for batch converting Excel files to CSV format with progress tracking and error handling.

